// specs/booking-extranet-intake.md rule 35 (audit r5) — the webhook secret is created and regenerated by the secret
// routes only: a PUT on the generic settings route is refused, `keySet` still reads, and the routes keep working.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');
const Database = require('better-sqlite3');

process.env.DB_PATH = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'gf-bi-key-')), 'core.db');
process.env.GUESTFLOW_ENCRYPTION_KEY = process.env.GUESTFLOW_ENCRYPTION_KEY || crypto.randomBytes(32).toString('base64');
const silent = console.log;
console.log = () => {};
require('../../../database');
console.log = silent;

const registry = require('../../sdk/registry');
const loader = require('../../loader');
const bookingIntake = require('..');
const { buildModel: buildPluginsModel } = require('../../../models/pluginsModel');
const { buildModel: buildPluginSettingsModel } = require('../../../models/pluginSettingsModel');
const { createController } = require('../../../controllers/pluginsController');
const { ensurePluginsTable, ensurePluginSettingsTable } = require('../../../utils/pluginsSchema');

const fakeRes = () => ({ statusCode: 200, body: null, status(c) { this.statusCode = c; return this; }, json(b) { this.body = b; return this; } });

test('rule 35: a PUT naming the secret is refused and changes nothing; keySet still reads', () => {
  const db = new Database(':memory:');
  db.exec(fs.readFileSync(path.join(__dirname, '..', '..', '..', 'schema.sql'), 'utf8'));
  ensurePluginsTable(db);
  ensurePluginSettingsTable(db);
  registry.reset();
  const plugins = buildPluginsModel(db);
  plugins.install('booking-intake');
  registry.configure({ isActive: (id) => plugins.isActive(id) });
  const settingsModel = buildPluginSettingsModel(db);
  loader.registerAll({ db, modules: [bookingIntake], settingsModel: () => settingsModel, isInstalled: (id) => Boolean(plugins.get(id)) });
  const controller = createController(plugins, { registry, settingsModel: () => settingsModel });
  settingsModel.set('booking-intake', 'key', 'generated-secret', { secret: true });
  const before = settingsModel.raw('booking-intake', 'key');

  for (const key of ['weak', null, '']) {
    const res = fakeRes();
    controller.saveSettings({ params: { id: 'booking-intake' }, body: { key } }, res);
    if (key === '') continue; // '' keeps a secret by the generic rule: nothing is written either way
    assert.equal(res.statusCode, 400);
    assert.equal(res.body.error, 'INVALID_SETTING');
    assert.match(res.body.errors.key, /Créer le secret/);
  }
  assert.equal(settingsModel.raw('booking-intake', 'key'), before);
  const view = fakeRes();
  controller.getSettings({ params: { id: 'booking-intake' } }, view);
  assert.equal(view.body.keySet, true);
});
